IF NOT EXISTS(SELECT 1 FROM dbo.RumboDestinations WHERE Id=N'macao') INSERT dbo.RumboDestinations VALUES(N'macao',N'Macao',33280,42,N'{"id":"macao","name":"Macao","country":"China (Macao)","type":"cultura","tag":"Encuentro de culturas","signature":"Plazas portuguesas y tradiciones cantonesas","intro":"Calles adoquinadas y fachadas históricas conviven con la energía contemporánea de Macao.","description":"Su centro histórico invita a caminar entre iglesias, templos y plazas. Taipa y Coloane aportan sabores macaneses, casas tradicionales y paseos tranquilos.","highlights":["Ruinas de San Pablo","Largo do Senado","Templo A-Má"],"tip":"Lleva calzado cómodo para cuestas y adoquines; reserva tiempo para trasladarte entre península e islas.","arrival":"Macao","transfer":"Autobús, taxi o conexión al tren ligero desde Taipa; traslado al hotel no incluido.","airport":{"code":"MFM","name":"Macau International"},"nights":3,"economy":33280,"duration":1740,"region":"internacional","image":"imagenes-viajes/destinos/destino-macao.jpg","thumbnail":"imagenes-viajes/destinos/miniaturas/macao.jpg","mediumImage":"imagenes-viajes/destinos/miniaturas/macao-1280.jpg","imageWidth":2560,"imageHeight":1709,"alt":"Panorámica de Macao con el Grand Lisboa junto al lago Nam Van","photoAuthor":"kewl","photoSource":"https://commons.wikimedia.org/wiki/File:Macau_-_Skyline.jpg","photoLicense":"CC BY 2.0","photoLicenseUrl":"https://creativecommons.org/licenses/by/2.0","imagePosition":"50% 50%","promotion":null,"inspirationBudget":41860}');
