IF NOT EXISTS(SELECT 1 FROM dbo.RumboDestinations WHERE Id=N'antalya') INSERT dbo.RumboDestinations VALUES(N'antalya',N'Antalya',27040,43,N'{"id":"antalya","name":"Antalya","country":"Turquía","type":"playa","tag":"Riviera turca","signature":"Historia junto al Mediterráneo","intro":"Antalya combina el casco antiguo de Kaleiçi con una costa de playas y acantilados.","description":"Recorre puertas romanas, callejones otomanos y el puerto antiguo. Fuera del centro, el Mediterráneo y las cascadas ofrecen jornadas al aire libre.","highlights":["Kaleiçi","Puerta de Adriano","Playa Konyaaltı"],"tip":"Reserva las caminatas para las horas frescas y distingue las cascadas Düden superiores de las inferiores.","arrival":"Antalya","transfer":"Tranvía o taxi autorizado hacia el centro; conexiones posteriores según hotel, no incluidas.","airport":{"code":"AYT","name":"Antalya"},"nights":5,"economy":27040,"duration":1380,"region":"internacional","image":"imagenes-viajes/destinos/destino-antalya.jpg","thumbnail":"imagenes-viajes/destinos/miniaturas/antalya.jpg","mediumImage":"imagenes-viajes/destinos/miniaturas/antalya-1280.jpg","imageWidth":2560,"imageHeight":1440,"alt":"Playa de Konyaaltı y montañas junto al Mediterráneo en Antalya","photoAuthor":"Esginmurat","photoSource":"https://commons.wikimedia.org/wiki/File:Falezlerden_Antalya_Konyaalt%C4%B1_Plaj%C4%B1na_do%C4%9Fru_bir_g%C3%B6r%C3%BCn%C3%BCm.jpg","photoLicense":"CC BY-SA 4.0","photoLicenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","imagePosition":"50% 50%","promotion":null,"inspirationBudget":38090}');
