IF NOT EXISTS(SELECT 1 FROM dbo.RumboDestinations WHERE Id=N'kuala-lumpur') INSERT dbo.RumboDestinations VALUES(N'kuala-lumpur',N'Kuala Lumpur',29380,44,N'{"id":"kuala-lumpur","name":"Kuala Lumpur","country":"Malasia","type":"cultura","tag":"Sabores y arquitectura","signature":"Una capital de muchas culturas","intro":"Torres relucientes, mercados y templos muestran la diversidad de Kuala Lumpur.","description":"Disfruta del entorno de las Petronas, la arquitectura del centro histórico y la cocina malaya, china e india. Los jardines urbanos permiten descansar del ritmo de la capital.","highlights":["Torres Petronas","Merdeka Square","Central Market"],"tip":"Usa el transporte urbano entre barrios y adapta la vestimenta al visitar lugares de culto.","arrival":"Kuala Lumpur","transfer":"KLIA Ekspres o autobús hasta KL Sentral; traslado y conexiones al hotel no incluidos.","airport":{"code":"KUL","name":"Kuala Lumpur International"},"nights":4,"economy":29380,"duration":1680,"region":"internacional","image":"imagenes-viajes/destinos/destino-kuala-lumpur.jpg","thumbnail":"imagenes-viajes/destinos/miniaturas/kuala-lumpur.jpg","mediumImage":"imagenes-viajes/destinos/miniaturas/kuala-lumpur-1280.jpg","imageWidth":2560,"imageHeight":1441,"alt":"Cruce de Bukit Bintang entre los edificios de Kuala Lumpur","photoAuthor":"Renek78","photoSource":"https://commons.wikimedia.org/wiki/File:Bukit_Bintang_junction_in_2024_2.jpg","photoLicense":"CC0","photoLicenseUrl":"http://creativecommons.org/publicdomain/zero/1.0/deed.en","imagePosition":"50% 50%","promotion":null,"inspirationBudget":35828}');
