IF NOT EXISTS(SELECT 1 FROM dbo.RumboDestinations WHERE Id=N'phuket') INSERT dbo.RumboDestinations VALUES(N'phuket',N'Phuket',31460,45,N'{"id":"phuket","name":"Phuket","country":"Tailandia","type":"playa","tag":"Mar de Andamán","signature":"Playas, miradores y casas de colores","intro":"La isla de Phuket ofrece playas tropicales y un casco antiguo de gran personalidad.","description":"Combina el ambiente de Phuket Town con calas de la costa oeste y atardeceres en el extremo sur. Cada zona de la isla propone un ritmo diferente.","highlights":["Phuket Old Town","Playa Kata","Cabo Promthep"],"tip":"Respeta las banderas de playa; el mar y las excursiones náuticas dependen del tiempo.","arrival":"Phuket","transfer":"Autobús, van o taxi autorizado hacia Phuket Town o las playas; traslado no incluido.","airport":{"code":"HKT","name":"Phuket International"},"nights":6,"economy":31460,"duration":1740,"region":"internacional","image":"imagenes-viajes/destinos/destino-phuket.jpg","thumbnail":"imagenes-viajes/destinos/miniaturas/phuket.jpg","mediumImage":"imagenes-viajes/destinos/miniaturas/phuket-1280.jpg","imageWidth":2560,"imageHeight":1440,"alt":"Arena y mar de la playa Patong en la isla de Phuket","photoAuthor":"jbremer57","photoSource":"https://commons.wikimedia.org/wiki/File:Patong_Beach_on_Phuket.jpg","photoLicense":"CC BY 2.0","photoLicenseUrl":"https://creativecommons.org/licenses/by/2.0","imagePosition":"50% 50%","promotion":null,"inspirationBudget":43940}');
