IF NOT EXISTS(SELECT 1 FROM dbo.RumboDestinations WHERE Id=N'pattaya') INSERT dbo.RumboDestinations VALUES(N'pattaya',N'Pattaya',30160,46,N'{"id":"pattaya","name":"Pattaya","country":"Tailandia","type":"playa","tag":"Costa del golfo","signature":"Una escapada costera desde Bangkok","intro":"Playas, miradores e islas cercanas definen esta ciudad del golfo de Tailandia.","description":"Elige entre el ambiente urbano de Pattaya, los paseos de Jomtien y una excursión marítima a Koh Lan. Sus templos y mercados completan la estancia.","highlights":["Playa Jomtien","Koh Lan","Santuario de la Verdad"],"tip":"Organiza la visita a Koh Lan según el estado del mar y confirma el último regreso.","arrival":"Bangkok","transfer":"Llegada aérea a Bangkok; continuar por carretera a Pattaya, aproximadamente 2–3 horas según tráfico. Traslado terrestre no incluido.","airport":{"code":"BKK","name":"Suvarnabhumi, Bangkok"},"nights":5,"economy":30160,"duration":1620,"region":"internacional","image":"imagenes-viajes/destinos/destino-pattaya.jpg","thumbnail":"imagenes-viajes/destinos/miniaturas/pattaya.jpg","mediumImage":"imagenes-viajes/destinos/miniaturas/pattaya-1280.jpg","imageWidth":2560,"imageHeight":1920,"alt":"Bahía y playa de Pattaya vistas desde un mirador","photoAuthor":"Sergey S. Dukachev","photoSource":"https://commons.wikimedia.org/wiki/File:Pattaya_beach_from_view_point.jpg","photoLicense":"CC BY-SA 3.0","photoLicenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","imagePosition":"50% 50%","promotion":null,"inspirationBudget":39260}');
