IF NOT EXISTS(SELECT 1 FROM dbo.RumboDestinations WHERE Id=N'taipei') INSERT dbo.RumboDestinations VALUES(N'taipei',N'Taipéi',30940,47,N'{"id":"taipei","name":"Taipéi","country":"Taiwán","type":"cultura","tag":"Templos y mercados","signature":"Una ciudad que se saborea caminando","intro":"Taipéi reúne templos tradicionales, mercados nocturnos y un horizonte dominado por Taipei 101.","description":"Los barrios históricos de Wanhua y Dadaocheng muestran otra cara de la ciudad. El metro facilita combinar patrimonio, cocina local y miradores verdes.","highlights":["Taipei 101","Templo Longshan","Mercado nocturno Raohe"],"tip":"Lleva una capa de lluvia ligera y consulta las condiciones del sendero de Xiangshan.","arrival":"Taipéi","transfer":"Airport MRT hasta Taipei Main Station o taxi autorizado; traslado no incluido.","airport":{"code":"TPE","name":"Taiwan Taoyuan International"},"nights":4,"economy":30940,"duration":1620,"region":"internacional","image":"imagenes-viajes/destinos/destino-taipei.jpg","thumbnail":"imagenes-viajes/destinos/miniaturas/taipei.jpg","mediumImage":"imagenes-viajes/destinos/miniaturas/taipei-1280.jpg","imageWidth":2560,"imageHeight":1706,"alt":"Panorámica de Taipéi con la torre Taipei 101","photoAuthor":"毛貓大少爺","photoSource":"https://commons.wikimedia.org/wiki/File:Taipei_Skyline_2022.06.29.jpg","photoLicense":"CC BY-SA 2.0","photoLicenseUrl":"https://creativecommons.org/licenses/by-sa/2.0","imagePosition":"50% 50%","promotion":null,"inspirationBudget":40820}');
