IF NOT EXISTS(SELECT 1 FROM dbo.RumboDestinations WHERE Id=N'budapest') INSERT dbo.RumboDestinations VALUES(N'budapest',N'Budapest',23920,51,N'{"id":"budapest","name":"Budapest","country":"Hungría","type":"cultura","tag":"Danubio y termas","signature":"Dos orillas con historias propias","intro":"Buda y Pest se miran sobre el Danubio entre palacios, puentes y arquitectura monumental.","description":"Alterna el barrio del castillo con los mercados de Pest y sus parques. Las termas forman parte de la experiencia urbana y requieren tiempo propio.","highlights":["Parlamento de Hungría","Bastión de los Pescadores","Puente de las Cadenas"],"tip":"Reserva con anticipación visitas al Parlamento y consulta las normas de cada baño termal.","arrival":"Budapest","transfer":"Autobús del aeropuerto o taxi autorizado hacia el centro; traslado no incluido.","airport":{"code":"BUD","name":"Budapest Ferenc Liszt International"},"nights":4,"economy":23920,"duration":1140,"region":"internacional","image":"imagenes-viajes/destinos/destino-budapest.jpg","thumbnail":"imagenes-viajes/destinos/miniaturas/budapest.jpg","mediumImage":"imagenes-viajes/destinos/miniaturas/budapest-1280.jpg","imageWidth":2500,"imageHeight":1293,"alt":"Río Danubio y puentes de Budapest desde la colina Gellért","photoAuthor":"Visions of Domino","photoSource":"https://commons.wikimedia.org/wiki/File:View_from_Gell%C3%A9rt_Hill_to_the_Danube,_Hungary_-_Budapest_(28493220635).jpg","photoLicense":"CC BY 2.0","photoLicenseUrl":"https://creativecommons.org/licenses/by/2.0","imagePosition":"50% 50%","promotion":null,"inspirationBudget":32448}');
