IF NOT EXISTS(SELECT 1 FROM dbo.RumboDestinations WHERE Id=N'edimburgo') INSERT dbo.RumboDestinations VALUES(N'edimburgo',N'Edimburgo',24960,55,N'{"id":"edimburgo","name":"Edimburgo","country":"Reino Unido","type":"cultura","tag":"Castillo y callejones","signature":"Una capital entre piedra y colinas","intro":"Edimburgo combina el trazado medieval de Old Town con jardines y miradores volcánicos.","description":"Su castillo domina calles donde conviven historias, museos y cafés. New Town y los paseos panorámicos completan una estancia de ritmo caminable.","highlights":["Castillo de Edimburgo","Royal Mile","Calton Hill"],"tip":"Usa calzado con agarre; las cuestas y adoquines pueden estar húmedos incluso en días suaves.","arrival":"Edimburgo","transfer":"Tranvía, autobús o taxi hacia el centro; traslado no incluido.","airport":{"code":"EDI","name":"Edimburgo"},"nights":4,"economy":24960,"duration":1080,"region":"internacional","image":"imagenes-viajes/destinos/destino-edimburgo.jpg","thumbnail":"imagenes-viajes/destinos/miniaturas/edimburgo.jpg","mediumImage":"imagenes-viajes/destinos/miniaturas/edimburgo-1280.jpg","imageWidth":2560,"imageHeight":1440,"alt":"Panorámica de los edificios históricos de Edimburgo","photoAuthor":"Andrew Colin","photoSource":"https://commons.wikimedia.org/wiki/File:Skyline_of_Edinburgh.jpg","photoLicense":"CC BY 2.0","photoLicenseUrl":"https://creativecommons.org/licenses/by/2.0","imagePosition":"50% 50%","promotion":null,"inspirationBudget":39520}');
