IF NOT EXISTS(SELECT 1 FROM dbo.RumboDestinations WHERE Id=N'hanoi') INSERT dbo.RumboDestinations VALUES(N'hanoi',N'Hanói',29380,58,N'{"id":"hanoi","name":"Hanói","country":"Vietnam","type":"cultura","tag":"Lagos y vida local","signature":"La capital de los callejones y el café","intro":"Hanói combina lagos, templos y la energía de sus calles comerciales tradicionales.","description":"En el casco antiguo, cada calle revela oficios y aromas propios. Los paseos junto al agua y los monumentos históricos equilibran el ritmo de la capital.","highlights":["Lago Hoan Kiem","Barrio Antiguo","Templo de la Literatura"],"tip":"Cruza las calles con calma y elige recorridos a pie cortos para disfrutar mejor del casco antiguo.","arrival":"Hanói","transfer":"Autobús o taxi autorizado hacia Hanói; traslado al hotel no incluido.","airport":{"code":"HAN","name":"Noi Bai International"},"nights":4,"economy":29380,"duration":1740,"region":"internacional","image":"imagenes-viajes/destinos/destino-hanoi.jpg","thumbnail":"imagenes-viajes/destinos/miniaturas/hanoi.jpg","mediumImage":"imagenes-viajes/destinos/miniaturas/hanoi-1280.jpg","imageWidth":2048,"imageHeight":1093,"alt":"Panorámica de Hanói con la montaña Ba Vì al fondo","photoAuthor":"Quangnlnhe182394","photoSource":"https://commons.wikimedia.org/wiki/File:Hanoi_skyline_with_Ba_Vi_Mountain.jpg","photoLicense":"CC0","photoLicenseUrl":"http://creativecommons.org/publicdomain/zero/1.0/deed.en","imagePosition":"50% 50%","promotion":null,"inspirationBudget":35412}');
