IF NOT EXISTS(SELECT 1 FROM dbo.RumboDestinations WHERE Id=N'agra') INSERT dbo.RumboDestinations VALUES(N'agra',N'Agra',28080,62,N'{"id":"agra","name":"Agra","country":"India","type":"cultura","tag":"Arquitectura mogola","signature":"Mármol y jardines a orillas del Yamuna","intro":"Agra invita a descubrir el Taj Mahal y otras grandes obras del patrimonio mogol.","description":"Organiza la visita al Taj con tiempo y completa el viaje con fortalezas, jardines y mercados. Las vistas desde la otra orilla muestran un paisaje diferente.","highlights":["Taj Mahal","Fuerte de Agra","Mehtab Bagh"],"tip":"Confirma el calendario de apertura del Taj Mahal: la visita turística cierra los viernes.","arrival":"Delhi","transfer":"Llegada aérea a Delhi; continuar a Agra por carretera o tren con conexión terrestre. Reserva una jornada de traslado y verifica horarios. No está incluido.","airport":{"code":"DEL","name":"Indira Gandhi International, Delhi"},"nights":3,"economy":28080,"duration":1500,"region":"internacional","image":"imagenes-viajes/destinos/destino-agra.jpg","thumbnail":"imagenes-viajes/destinos/miniaturas/agra.jpg","mediumImage":"imagenes-viajes/destinos/miniaturas/agra-1280.jpg","imageWidth":2560,"imageHeight":1683,"alt":"Taj Mahal y su estanque reflectante en Agra","photoAuthor":"Yann (talk)","photoSource":"https://commons.wikimedia.org/wiki/File:Taj_Mahal,_Agra,_India.jpg","photoLicense":"CC BY-SA 4.0","photoLicenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","imagePosition":"50% 50%","promotion":null,"inspirationBudget":33150}');
