IF NOT EXISTS(SELECT 1 FROM dbo.RumboDestinations WHERE Id=N'jaipur') INSERT dbo.RumboDestinations VALUES(N'jaipur',N'Jaipur',29120,63,N'{"id":"jaipur","name":"Jaipur","country":"India","type":"cultura","tag":"Palacios y bazares","signature":"La ciudad rosa de Rajasthan","intro":"Jaipur ofrece palacios, observatorios y mercados de artesanía en un entorno de colinas.","description":"El trazado de la ciudad vieja facilita combinar monumentos y bazares. Amber merece una salida propia para recorrer su fortaleza y sus alrededores.","highlights":["Hawa Mahal","City Palace","Fuerte Amber"],"tip":"Protege tu visita del calor y planifica los fuertes con vehículo reservado por separado.","arrival":"Jaipur","transfer":"Taxi autorizado hacia Jaipur; traslado al alojamiento no incluido.","airport":{"code":"JAI","name":"Jaipur International"},"nights":4,"economy":29120,"duration":1620,"region":"internacional","image":"imagenes-viajes/destinos/destino-jaipur.jpg","thumbnail":"imagenes-viajes/destinos/miniaturas/jaipur.jpg","mediumImage":"imagenes-viajes/destinos/miniaturas/jaipur-1280.jpg","imageWidth":1920,"imageHeight":1440,"alt":"Fachada rosa del Hawa Mahal en Jaipur","photoAuthor":"Chainwit.","photoSource":"https://commons.wikimedia.org/wiki/File:East_facade_Hawa_Mahal_Jaipur_from_ground_level_(July_2022)_-_img_01.jpg","photoLicense":"CC BY-SA 4.0","photoLicenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","imagePosition":"50% 50%","promotion":null,"inspirationBudget":36192}');
