IF NOT EXISTS(SELECT 1 FROM dbo.RumboDestinations WHERE Id=N'el-cairo') INSERT dbo.RumboDestinations VALUES(N'el-cairo',N'El Cairo',26520,64,N'{"id":"el-cairo","name":"El Cairo","country":"Egipto","type":"cultura","tag":"Patrimonio del Nilo","signature":"Una ciudad junto a milenios de historia","intro":"El Cairo permite combinar barrios históricos con los grandes monumentos de la región de Giza.","description":"Explora sus mercados y museos en jornadas separadas. Las pirámides se encuentran en Giza y requieren un traslado desde el centro de El Cairo.","highlights":["Pirámides de Giza","Museo Egipcio","Khan el-Khalili"],"tip":"Reserva tiempo adicional para el tráfico entre El Cairo y Giza, especialmente al volver al aeropuerto.","arrival":"El Cairo","transfer":"Taxi autorizado o traslado reservado hacia El Cairo o Giza; servicio terrestre no incluido.","airport":{"code":"CAI","name":"El Cairo International"},"nights":5,"economy":26520,"duration":1380,"region":"internacional","image":"imagenes-viajes/destinos/destino-el-cairo.jpg","thumbnail":"imagenes-viajes/destinos/miniaturas/el-cairo.jpg","mediumImage":"imagenes-viajes/destinos/miniaturas/el-cairo-1280.jpg","imageWidth":2560,"imageHeight":1700,"alt":"Ópera de El Cairo, parque Al Hurriyah y río Nilo","photoAuthor":"Jorge Láscar from Melbourne, Australia","photoSource":"https://commons.wikimedia.org/wiki/File:Cairo_Opera_House,_Al_Hurriyah_Park_and_the_Nile_river_(14797782354).jpg","photoLicense":"CC BY 2.0","photoLicenseUrl":"https://creativecommons.org/licenses/by/2.0","imagePosition":"50% 50%","promotion":null,"inspirationBudget":36660}');
