IF NOT EXISTS(SELECT 1 FROM dbo.RumboDestinations WHERE Id=N'meca') INSERT dbo.RumboDestinations VALUES(N'meca',N'La Meca',29380,67,N'{"id":"meca","name":"La Meca","country":"Arabia Saudita","type":"cultura","tag":"Patrimonio espiritual","signature":"Un destino sagrado para viajeros musulmanes","intro":"La Meca es un centro de peregrinación y patrimonio islámico con acceso reservado a musulmanes.","description":"La estancia debe organizarse según los requisitos oficiales de entrada y peregrinación. Las propuestas culturales son de demostración y no incluyen permisos ni servicios de Hajj o Umrah.","highlights":["Masjid al-Haram","Hira Cultural District","Abraj Al Bait"],"tip":"Acceso solo para musulmanes. Verifica visado, permisos y restricciones estacionales oficiales; una reserva demo no autoriza la peregrinación.","arrival":"Yeda","transfer":"Llegada aérea a Yeda; continuar a La Meca en tren Haramain con enlace local o por carretera. Traslado y permisos no incluidos.","airport":{"code":"JED","name":"Rey Abdulaziz International, Yeda"},"nights":5,"economy":29380,"duration":1500,"region":"internacional","image":"imagenes-viajes/destinos/destino-meca.jpg","thumbnail":"imagenes-viajes/destinos/miniaturas/meca.jpg","mediumImage":"imagenes-viajes/destinos/miniaturas/meca-1280.jpg","imageWidth":2560,"imageHeight":1722,"alt":"Gran Mezquita y Kaaba en La Meca","photoAuthor":"Saudipics.com","photoSource":"https://commons.wikimedia.org/wiki/File:Great_Mosque_of_Mecca1.jpg","photoLicense":"CC BY-SA 4.0","photoLicenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","imagePosition":"50% 50%","promotion":null,"inspirationBudget":44980}');
